function NfoDeckIcon({ kind, size = 20 }) {
  return <img src={NFO_DECK_ICONS[kind] || NFO_DECK_ICONS.all} alt="" aria-hidden="true" style={{
    display: "block", width: size, height: size, flexShrink: 0, objectFit: "contain",
  }} />;
}

function SocketToken({ x, y, size, src, alt }) {
  return <img src={src} alt={alt} style={{
    position: "absolute", left: `${x}%`, top: `${y}%`, width: `${size}%`,
    transform: "translate(-50%, -50%)", transformOrigin: "center",
    pointerEvents: "none", display: "block",
  }} />;
}
