const avatarArtForCard = (moduleKey, card) => {
  if (!card) return null;
  if (moduleKey === "primary") return NFO_CHARACTER_ART[card.id] || NFO_CARD_ART[card.id] || card.img || null;
  return CARD_ART[card.id] || card.img || null;
};

const CHARACTER_AVATARS = Object.entries(MODULES).flatMap(([moduleKey, module]) =>
  module.CARDS
    .filter((card) => (card.r === "common" || card.r === "uncommon") && avatarArtForCard(moduleKey, card))
    .slice(0, 14)
    .map((card) => ({
      value: `card:${moduleKey}:${card.id}`,
      moduleKey,
      moduleName: SET_DISPLAY_NAMES[moduleKey],
      name: card.name,
      art: avatarArtForCard(moduleKey, card),
    }))
);

const DEFAULT_AVATAR = CHARACTER_AVATARS[0]?.value || "🦘";
const avatarChoiceFor = (value) => CHARACTER_AVATARS.find((choice) => choice.value === value);

function AvatarBadge({ value, size = 48, className = "" }) {
  const choice = avatarChoiceFor(value) || CHARACTER_AVATARS[0];
  if (!choice) return <span className={className} style={{ fontSize: size * 0.72, lineHeight: 1 }}>🦘</span>;
  return <img className={className} src={choice.art} alt={choice.name} title={choice.name} style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", objectPosition: "50% 25%", display: "block" }} />;
}

