  const m = MODULES[key] || MODULES.junior;
  setActiveModuleKey(m.key);
  setModuleActiveVars(m.examKindFor, m.EXAM_PASS_MARKS, m.RARITY, m.CARD_CLASS, m.CARDS); BOSS_ART = m.BOSS_ART;
