  setModuleSharedVars(m.TOPICS, m.DEEP_TOPICS, m.G); CONCEPTS = m.CONCEPTS;
  OLYMPIAD = m.OLYMPIAD; OLYMPIAD_PLAYBOOK = m.OLYMPIAD_PLAYBOOK; ACADEMY = m.ACADEMY;
