function TrigCalcModal({ onClose }) {
  const [mode, setMode] = useState("forward"); // "forward" = angle→ratio, "inverse" = ratio→angle
  const [input, setInput] = useState("");
  const [result, setResult] = useState(null);
  const [fn, setFn] = useState(null);
  const calc = (f) => {
    const v = parseFloat(input);
    if (isNaN(v)) { setResult("Enter a value first"); setFn(null); return; }
    let out;
    if (mode === "forward") {
      const r = v * Math.PI / 180;
      if (f === "sin") out = Math.sin(r);
      else if (f === "cos") out = Math.cos(r);
      else out = Math.tan(r);
    } else {
      if (Math.abs(v) > 1 && f !== "tan") { setResult("Value must be between −1 and 1"); setFn(null); return; }
      if (f === "sin") out = Math.asin(v) * 180 / Math.PI;
      else if (f === "cos") out = Math.acos(v) * 180 / Math.PI;
      else out = Math.atan(v) * 180 / Math.PI;
    }
    setFn(f); setResult(Math.round(out * 1e4) / 1e4);
  };
  const fwdLabel = (f) => mode === "forward" ? f : `${f}⁻¹`;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(8,4,16,.62)", backdropFilter: "blur(3px)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 300, padding: 20 }} onClick={onClose}>
      <div style={{ background: "#fdf8ef", borderRadius: 24, padding: 24, width: "100%", maxWidth: 360, boxShadow: "0 30px 80px rgba(0,0,0,.5)" }} onClick={e => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <span style={{ fontWeight: 800, fontSize: 18, color: T.ink }}>📐 Trig Calculator</span>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 20, color: T.inkSoft }}>✕</button>
        </div>
        <div style={{ display: "flex", background: "#ede8f8", borderRadius: 12, padding: 3, marginBottom: 16, gap: 3 }}>
          {[["forward", "sin / cos / tan"], ["inverse", "sin⁻¹ / cos⁻¹ / tan⁻¹"]].map(([m, label]) => (
            <button key={m} onClick={() => { setMode(m); setInput(""); setResult(null); setFn(null); }}
              style={{ flex: 1, padding: "8px 4px", borderRadius: 10, border: "none", cursor: "pointer", fontWeight: 700, fontSize: 13,
                background: mode === m ? T.violet : "transparent", color: mode === m ? "#fff" : T.inkSoft }}>{label}</button>
          ))}
        </div>
        <div style={{ marginBottom: 14 }}>
          <label style={{ fontWeight: 700, fontSize: 13, color: T.inkSoft, display: "block", marginBottom: 6 }}>
            {mode === "forward" ? "ANGLE (degrees)" : "VALUE (e.g. 0.5 for sin⁻¹, any for tan⁻¹)"}
          </label>
          <input type="number" value={input} onChange={e => { setInput(e.target.value); setResult(null); setFn(null); }}
            placeholder={mode === "forward" ? "e.g. 30" : "e.g. 0.5"}
            style={{ width: "100%", border: `2px solid ${T.violet}55`, borderRadius: 12, padding: "10px 14px", fontSize: 20, fontWeight: 700, color: T.ink, background: "#fff", boxSizing: "border-box", outline: "none" }} />
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 16 }}>
          {["sin", "cos", "tan"].map(f => (
            <button key={f} onClick={() => calc(f)} style={{ background: fn === f ? T.violet : T.violet + "18", color: fn === f ? "#fff" : T.violet, border: `2px solid ${T.violet}44`, borderRadius: 14, padding: "13px 0", fontWeight: 800, fontSize: 17, cursor: "pointer" }}>{fwdLabel(f)}</button>
          ))}
        </div>
        <div style={{ minHeight: 52, background: T.violet + "12", border: `2px solid ${T.violet}33`, borderRadius: 14, padding: "12px 16px", display: "flex", alignItems: "center", justifyContent: "center" }}>
          {result === null
            ? <span style={{ color: T.inkSoft, fontWeight: 700, fontSize: 14 }}>Result appears here</span>
            : typeof result === "string"
              ? <span style={{ color: T.coral, fontWeight: 700, fontSize: 15 }}>{result}</span>
              : mode === "forward"
                ? <span style={{ fontWeight: 800, fontSize: 22, color: T.ink }}>{fn}({input}°) = {result}</span>
                : <span style={{ fontWeight: 800, fontSize: 22, color: T.ink }}>{fn}⁻¹({input}) = {result}°</span>}
        </div>
      </div>
    </div>
  );
}

function NotepadPanel({ progress, setProgress, onClose }) {
  const notepad = progress.notepad || freshNotepad();
  const pageIndex = notepad.page || 0;
  const pageData = notepad.pages[pageIndex] || { text: "", strokes: [] };
  const [mode, setMode] = useState("type"); // "type" | "draw"
  const canvasRef = useRef(null);
  const drawingRef = useRef(false);
  const currentStrokeRef = useRef([]);

  const updateNotepad = useCallback((updater) => {
    setProgress((p) => {
      const np = p.notepad || freshNotepad();
      return { ...p, notepad: updater(np) };
    });
  }, [setProgress]);

  const setPage = (idx) => {
    const clamped = Math.max(0, Math.min(NOTEPAD_PAGES - 1, idx));
    updateNotepad((np) => ({ ...np, page: clamped }));
  };
  const setPageText = (text) => {
    updateNotepad((np) => {
      const pages = np.pages.slice();
      pages[pageIndex] = { ...(pages[pageIndex] || { strokes: [] }), text };
      return { ...np, pages };
    });
  };
  const commitStroke = (points) => {
    if (points.length < 2) return;
    updateNotepad((np) => {
      const pages = np.pages.slice();
      const page = pages[pageIndex] || { text: "", strokes: [] };
      pages[pageIndex] = { ...page, strokes: [...page.strokes, points] };
      return { ...np, pages };
    });
  };
  const clearPage = () => {
    updateNotepad((np) => {
      const pages = np.pages.slice();
      pages[pageIndex] = { text: "", strokes: [] };
      return { ...np, pages };
    });
  };

  const redraw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    const ctx = canvas.getContext("2d");
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, rect.width, rect.height);
    ctx.strokeStyle = "#2a3a6e"; ctx.lineWidth = 2.5; ctx.lineCap = "round"; ctx.lineJoin = "round";
    const strokes = pageData.strokes || [];
    for (const stroke of strokes) {
      if (!stroke || stroke.length < 2) continue;
      ctx.beginPath();
      ctx.moveTo(stroke[0][0] * rect.width, stroke[0][1] * rect.height);
      for (let i = 1; i < stroke.length; i++) ctx.lineTo(stroke[i][0] * rect.width, stroke[i][1] * rect.height);
      ctx.stroke();
    }
  }, [pageData.strokes]);

  useEffect(() => { redraw(); }, [redraw, pageIndex]);
  useEffect(() => {
    const onResize = () => redraw();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [redraw]);

  const getPoint = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    return [(clientX - rect.left) / rect.width, (clientY - rect.top) / rect.height];
  };
  const startDraw = (e) => {
    if (mode !== "draw") return;
    e.preventDefault();
    drawingRef.current = true;
    currentStrokeRef.current = [getPoint(e)];
  };
  const moveDraw = (e) => {
    if (!drawingRef.current) return;
    e.preventDefault();
    const pt = getPoint(e);
    const pts = currentStrokeRef.current;
    pts.push(pt);
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const ctx = canvas.getContext("2d");
    const a = pts[pts.length - 2], b = pts[pts.length - 1];
    if (a) {
      ctx.strokeStyle = "#2a3a6e"; ctx.lineWidth = 2.5; ctx.lineCap = "round"; ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(a[0] * rect.width, a[1] * rect.height);
      ctx.lineTo(b[0] * rect.width, b[1] * rect.height);
      ctx.stroke();
    }
  };
  const endDraw = () => {
    if (!drawingRef.current) return;
    drawingRef.current = false;
    commitStroke(currentStrokeRef.current);
    currentStrokeRef.current = [];
  };

  return (
    <div className="kq-notepad-backdrop" onClick={onClose}>
      <div className="kq-notepad-panel" onClick={(e) => e.stopPropagation()}>
        <div className="kq-notepad-toolbar">
          <button className={"kq-notepad-mode-btn" + (mode === "type" ? " active" : "")} onClick={() => setMode("type")}><Type size={15} /> Type</button>
          <button className={"kq-notepad-mode-btn" + (mode === "draw" ? " active" : "")} onClick={() => setMode("draw")}><PenLine size={15} /> Draw</button>
          <button className="kq-notepad-icon-btn" title="Clear this page" onClick={clearPage}><Eraser size={16} /></button>
          <div className="kq-notepad-toolbar-spacer" />
          <button className="kq-notepad-icon-btn" title="Previous page" onClick={() => setPage(pageIndex - 1)} disabled={pageIndex === 0} style={pageIndex === 0 ? { opacity: .35, cursor: "default" } : undefined}><ArrowLeft size={16} /></button>
          <span className="kq-notepad-page-label">Page {pageIndex + 1} / {NOTEPAD_PAGES}</span>
          <button className="kq-notepad-icon-btn" title="Next page" onClick={() => setPage(pageIndex + 1)} disabled={pageIndex === NOTEPAD_PAGES - 1} style={pageIndex === NOTEPAD_PAGES - 1 ? { opacity: .35, cursor: "default" } : undefined}><ArrowRight size={16} /></button>
          <button className="kq-notepad-icon-btn" title="Close notepad" onClick={onClose}><X size={16} /></button>
        </div>
        <div className="kq-notepad-page">
          <textarea
            className="kq-notepad-textarea"
            value={pageData.text || ""}
            onChange={(e) => setPageText(e.target.value)}
            placeholder={mode === "type" ? "Jot your working out here..." : ""}
            style={{ pointerEvents: mode === "type" ? "auto" : "none" }}
          />
          <canvas
            ref={canvasRef}
            className="kq-notepad-canvas"
            style={{ pointerEvents: mode === "draw" ? "auto" : "none" }}
            onMouseDown={startDraw} onMouseMove={moveDraw} onMouseUp={endDraw} onMouseLeave={endDraw}
            onTouchStart={startDraw} onTouchMove={moveDraw} onTouchEnd={endDraw}
          />
        </div>
      </div>
    </div>
  );
}
function Confetti() {
  const colors = [T.coral, T.yellow, T.teal, T.violet, T.pink, T.green];
  return (<div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 60 }}>
    {Array.from({ length: 46 }).map((_, i) => { const left = Math.random() * 100, delay = Math.random() * 0.5, dur = 1.1 + Math.random() * 1.1, size = 7 + Math.random() * 8;
      return <div key={i} style={{ position: "absolute", top: -20, left: left + "%", width: size, height: size * 1.3, background: colors[i % colors.length], borderRadius: 2, animation: `kq-fall ${dur}s ${delay}s ease-in forwards` }} />; })}
  </div>);
}
function Mascot({ mood = "happy", line, size = 64 }) {
  return (<div style={{ display: "flex", alignItems: "center", gap: 12 }}>
    <img src={TITLE_ART.mascot} alt="" className={mood === "win" ? "kq-hop" : "kq-float"} style={{ width: size, height: size, objectFit: "contain", flexShrink: 0, filter: "drop-shadow(0 4px 8px rgba(0,0,0,.25))" }} />
    {line && <div className="kq-pop" style={{ position: "relative", background: T.white, color: T.ink, padding: "10px 14px", borderRadius: 16, fontWeight: 700, maxWidth: 380, fontSize: 15, boxShadow: "0 6px 0 rgba(42,26,94,.12)" }}>{line}
      <span style={{ position: "absolute", left: -8, top: 18, width: 0, height: 0, borderTop: "7px solid transparent", borderBottom: "7px solid transparent", borderRight: `9px solid ${T.white}` }} /></div>}
  </div>);
}
// A dim/silhouette base image with a second "revealed" image clipped in from the bottom
// up, as pct climbs from 0 to 100 — used for the orchard tree (stars-to-pack) and
// scarecrow (boss strength) foreground meters. Both images must share exact pixel
// dimensions (the embed script derives the dim version from the vivid one) so the crop
// lines up. Purely decorative — no click handling.
// A simple vertical thermometer-style meter: fills bottom-up inside the same ornate
// wood-frame border used elsewhere, with a small icon riding the top of the fill level.
function FillBar({ pct, colorTop, colorBottom, icon, title, onClick, style, ...rest }) {
  const clamped = Math.max(0, Math.min(100, pct));
  return (<div title={title} onClick={onClick} style={{ position: "relative", cursor: onClick ? "pointer" : "default", border: "14px solid transparent", borderImage: `url(${UI_ART.panelFrame}) 10% 13% / 14px stretch`, borderRadius: 10, overflow: "hidden", background: "rgba(28,19,48,.12)", ...style }} {...rest}>
    <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: clamped + "%", background: `linear-gradient(180deg, ${colorTop}, ${colorBottom})`, transition: "height .6s ease" }} />
    {icon && <img src={icon} alt="" style={{ position: "absolute", left: "50%", bottom: `calc(${clamped}% - 18px)`, transform: "translateX(-50%)", width: 34, height: 34, objectFit: "contain", transition: "bottom .6s ease", filter: "drop-shadow(0 2px 4px rgba(0,0,0,.45))" }} />}
  </div>);
}
function Btn({ children, color = T.violet, onClick, disabled, full, small, ghost, style }) {
  const [down, setDown] = useState(false);
  return (<button disabled={disabled} onMouseDown={() => setDown(true)} onMouseUp={() => setDown(false)} onMouseLeave={() => setDown(false)} onClick={onClick}
    style={{ fontFamily: "Fredoka, sans-serif", fontWeight: 600, fontSize: small ? 15 : 18, color: ghost ? color : T.white, background: ghost ? "transparent" : color, border: ghost ? `2.5px solid ${color}` : "none", padding: small ? "9px 16px" : "13px 22px", borderRadius: 16, cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.5 : 1, width: full ? "100%" : "auto", boxShadow: ghost ? "none" : `0 ${down ? 1 : 5}px 0 rgba(0,0,0,.22)`, transform: down ? "translateY(4px)" : "none", transition: "transform .06s, box-shadow .06s", display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8, ...style }}>{children}</button>);
}
function NamePlateButton({ activeModule, children, onClick, disabled, compact = false, style }) {
  const namePlate = activeModule === "intermediate" ? GF_NAME_PLATE : LR_NAME_PLATE;
  return <button className={`kq-oly-nameplate${compact ? " compact" : ""}`} style={{ "--oly-nameplate": `url(${namePlate})`, ...style }} onClick={onClick} disabled={disabled}><span>{children}</span></button>;
}
function Card({ children, style, ...rest }) { return <div style={{ background: T.white, borderRadius: 24, padding: 22, boxShadow: "0 10px 0 rgba(42,26,94,.08), 0 18px 40px rgba(42,26,94,.10)", ...style }} {...rest}>{children}</div>; }
// Shared "quest" chrome, reused across every hub/browse screen. QUEST_CARD (the ornate
// gold border-image frame) is reserved for the few large, singular boxes per screen —
// it read as too heavy when applied to every card. LITE_CARD (parchment tint + thin gold
// border, no frame art) is for everything smaller or repeated (tile grids, list rows).
// Recomputed per-render (not a frozen constant) so each module's own panelFrame art
// is picked up after activateModule() reassigns the UI_ART binding.
function getQuestCard() { return { background: `linear-gradient(160deg, ${T.parchment}, ${T.parchment2})`, border: "28px solid transparent", borderImage: `url(${UI_ART.panelFrame}) 10% 13% / 28px stretch`, borderRadius: 10, boxShadow: `0 10px 0 rgba(28,19,48,.18), 0 20px 44px rgba(28,19,48,.30)` }; }
const LITE_CARD = { background: `linear-gradient(160deg, ${T.parchment}, ${T.parchment2})`, border: `2px solid ${T.gold}55`, boxShadow: `0 10px 0 rgba(28,19,48,.18), 0 20px 44px rgba(28,19,48,.30)` };
const PROGRESS_TRACK = { height: 14, background: "rgba(28,19,48,.12)", borderRadius: 8, overflow: "hidden", boxShadow: "inset 0 2px 4px rgba(28,19,48,.18)" };
function Diagram({ svg }) { if (!svg) return null; return <div className="kq-diagram" style={{ margin: "16px 0", padding: "10px", background: "#faf8ff", borderRadius: 16 }} dangerouslySetInnerHTML={{ __html: svg }} />; }
function Lesson({ topic, color }) {
  const c = CONCEPTS[topic]; if (!c) return null;
  return (<div style={{ background: color + "14", border: `2px solid ${color}55`, borderRadius: 16, padding: "14px 16px", marginBottom: 14 }}>
    <div className="kq-display" style={{ fontWeight: 700, color: T.ink, fontSize: 16, display: "flex", alignItems: "center", gap: 6, marginBottom: 6 }}><BookOpen size={17} color={color} /> Key idea</div>
    <div style={{ color: T.ink, fontWeight: 700, marginBottom: 8 }}>{c.idea}</div>
    <ul style={{ margin: 0, paddingLeft: 18, color: T.inkSoft, fontWeight: 600, lineHeight: 1.6 }}>{c.method.map((m, i) => <li key={i}>{m}</li>)}</ul>
    {c.tip && <div style={{ marginTop: 8, fontWeight: 700, color: color }}>💡 {c.tip}</div>}
    {c.watch && <div style={{ marginTop: 8, fontWeight: 700, color: T.coral, background: T.coral + "12", borderRadius: 10, padding: "8px 12px" }}>⚠️ Watch out: {c.watch}</div>}
  </div>);
}

/* Rich guided lesson renderer (data from LESSONS in kq-content.js). Long, first
   principles, worked examples and reveal-answer check questions. Falls back to the
   compact Lesson card for topics that do not yet have a rich lesson. */
function LessonVisual({ type }) {
  if (type === "primary-rounding-23") return <figure className="kq-lesson-figure"><img src={PRIMARY_ROUNDING_ART} alt="A number line showing that 23 is three steps from 20 and seven steps from 30" /><figcaption>Twenty-three is nearer to 20 than to 30.</figcaption></figure>;
  if (type === "primary-multiplication-area") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 250" role="img" aria-label="An exact six by twenty-four array split into six by twenty and six by four"><rect x="28" y="35" width="600" height="180" rx="8" fill="#e9f1c8" stroke="#5c7136" strokeWidth="3"/><rect x="528" y="35" width="100" height="180" fill="#ffe2a5" stroke="#9b6820" strokeWidth="3"/>{Array.from({length:6},(_,r)=>Array.from({length:24},(_,c)=><circle key={`${r}-${c}`} cx={40+c*25} cy={50+r*30} r="6" fill={c<20?"#74a447":"#e5a52e"}/>))}<text x="278" y="25" textAnchor="middle">20</text><text x="578" y="25" textAnchor="middle">4</text><text x="14" y="132" textAnchor="middle">6</text><text x="278" y="132" textAnchor="middle">120</text><text x="578" y="132" textAnchor="middle">24</text><text x="328" y="240" textAnchor="middle">144</text></svg><figcaption>Six groups of 24 split into six groups of 20 and six groups of 4.</figcaption></figure>;
  if (type === "primary-division-groups") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 245" role="img" aria-label="Twelve apples shared equally into three baskets"><defs><symbol id="lessonApple" viewBox="0 0 30 34"><circle cx="15" cy="19" r="11" fill="#91b94d" stroke="#496526" strokeWidth="2"/><path d="M15 8q0-7 5-8" fill="none" stroke="#60431f" strokeWidth="2"/><path d="M19 4q7-3 9 2q-6 4-9-2" fill="#65a044"/></symbol></defs>{[0,1,2].map(g=><g key={g} transform={`translate(${40+g*230} 20)`}><path d="M10 90h180l-18 120H28z" fill="#d6a85c" stroke="#765124" strokeWidth="4"/><path d="M30 88q70-90 140 0" fill="none" stroke="#765124" strokeWidth="7"/>{[0,1,2,3].map(i=><use key={i} href="#lessonApple" x={42+(i%2)*62} y={92+Math.floor(i/2)*52} width="38" height="42"/>)}</g>)}</svg><figcaption>Twelve apples shared equally into three baskets gives four apples in each basket.</figcaption></figure>;
  if (type === "primary-equivalent-fractions") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 240" role="img" aria-label="Fraction strips showing one half equals two quarters"><text x="38" y="68">1/2</text><rect x="120" y="30" width="520" height="62" rx="7" fill="#fffaf0" stroke="#6d5431" strokeWidth="3"/><rect x="120" y="30" width="260" height="62" rx="6" fill="#dda8e8"/><line x1="380" y1="30" x2="380" y2="92" stroke="#6d5431" strokeWidth="3"/><text x="38" y="180">2/4</text><rect x="120" y="142" width="520" height="62" rx="7" fill="#fffaf0" stroke="#6d5431" strokeWidth="3"/><rect x="120" y="142" width="260" height="62" rx="6" fill="#dda8e8"/>{[1,2,3].map(i=><line key={i} x1={120+i*130} y1="142" x2={120+i*130} y2="204" stroke="#6d5431" strokeWidth="3"/>)}</svg><figcaption>The shaded length has not changed: 1/2 and 2/4 are two names for the same amount.</figcaption></figure>;
  if (type === "primary-ratio-groups") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 230" role="img" aria-label="Three repeated groups containing two green apples and three purple plums"><text x="360" y="28" textAnchor="middle">For every 2 apples, there are 3 plums</text>{[0,1,2].map(g=><g key={g} transform={`translate(${42+g*225} 48)`}><rect width="190" height="145" rx="18" fill="#fff8dc" stroke="#a9884e" strokeWidth="3"/>{[0,1].map(i=><circle key={`a${i}`} cx={58+i*72} cy="48" r="20" fill="#83ad43" stroke="#476524" strokeWidth="3"/>)}{[0,1,2].map(i=><circle key={`p${i}`} cx={35+i*60} cy="108" r="18" fill="#8752a8" stroke="#4f2768" strokeWidth="3"/>)}</g>)}</svg><figcaption>The group can repeat, but the relationship stays at 2:3.</figcaption></figure>;
  if (type === "primary-decimal-grid") return <figure className="kq-lesson-figure"><svg viewBox="0 0 500 500" role="img" aria-label="A hundred square with thirty-seven hundredths shaded">{Array.from({length:100},(_,i)=><rect key={i} x={25+(i%10)*45} y={25+Math.floor(i/10)*45} width="42" height="42" fill={i<37?"#75b7ae":"#fffaf0"} stroke="#765f3e"/>)}<text x="250" y="490" textAnchor="middle">37/100 = 0.37</text></svg><figcaption>Thirty-seven shaded hundredths can be written as 37/100 or 0.37.</figcaption></figure>;
  if (type === "primary-bar-model") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 260" role="img" aria-label="A bar model showing two numbers with total 30 and difference 6"><text x="30" y="74">larger</text><rect x="130" y="35" width="420" height="62" fill="#a9d6c7" stroke="#456f64" strokeWidth="3"/><rect x="550" y="35" width="90" height="62" fill="#f2bd66" stroke="#8c5d16" strokeWidth="3"/><text x="595" y="74" textAnchor="middle">6</text><text x="30" y="166">smaller</text><rect x="130" y="127" width="420" height="62" fill="#a9d6c7" stroke="#456f64" strokeWidth="3"/><path d="M130 220h510" stroke="#6d5431" strokeWidth="3"/><text x="385" y="248" textAnchor="middle">total 30</text></svg><figcaption>Remove the extra 6 first, then split what remains equally between the two matching bars.</figcaption></figure>;
  if (type === "primary-area-perimeter") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 280" role="img" aria-label="A five by three rectangle showing perimeter around the edge and area as square tiles">{Array.from({length:15},(_,i)=><rect key={i} x={150+(i%5)*82} y={25+Math.floor(i/5)*70} width="82" height="70" fill="#dce9b8" stroke="#9a844d"/>)}<rect x="150" y="25" width="410" height="210" fill="none" stroke="#7a3e8e" strokeWidth="10"/><text x="355" y="265" textAnchor="middle">15 square units inside</text><text x="590" y="132">16 units around</text></svg><figcaption>Area counts the square units inside. Perimeter measures the length around the edge.</figcaption></figure>;
  if (type === "primary-angle-types") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 250" role="img" aria-label="Acute, right and obtuse angles shown side by side">{[[120,190,45,"acute"],[360,190,90,"right"],[600,190,135,"obtuse"]].map(([x,y,a,label])=><g key={label}><line x1={x} y1={y} x2={x+75} y2={y} stroke="#51366d" strokeWidth="7" strokeLinecap="round"/><line x1={x} y1={y} x2={x+75*Math.cos(a*Math.PI/180)} y2={y-75*Math.sin(a*Math.PI/180)} stroke="#51366d" strokeWidth="7" strokeLinecap="round"/><text x={x} y="230" textAnchor="middle">{label}</text></g>)}</svg><figcaption>An acute angle is smaller than a right angle. An obtuse angle is larger than a right angle but smaller than a straight angle.</figcaption></figure>;
  if (type === "primary-reflection-grid") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 280" role="img" aria-label="A triangle and its mirror image on opposite sides of a vertical mirror line"><line x1="360" y1="15" x2="360" y2="265" stroke="#4a8ead" strokeWidth="6" strokeDasharray="12 10"/><polygon points="155,220 295,220 245,70" fill="#e5ac66" stroke="#784a19" strokeWidth="4"/><polygon points="565,220 425,220 475,70" fill="#dda8e8" stroke="#6d397b" strokeWidth="4"/>{[[155,565],[295,425],[245,475]].map(([a,b],i)=><line key={i} x1={a} y1={i===2?70:220} x2={b} y2={i===2?70:220} stroke="#9b8b70" strokeDasharray="6 8"/>)}</svg><figcaption>Each reflected corner is the same perpendicular distance from the mirror line.</figcaption></figure>;
  if (type === "primary-choice-tree") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 300" role="img" aria-label="A choice tree with two shirts and three pairs of trousers, making six outfits"><text x="55" y="155">start</text>{[[220,85,"red shirt"],[220,225,"blue shirt"]].map(([x,y,t],i)=><g key={t}><line x1="100" y1="150" x2={x} y2={y} stroke="#6c5738" strokeWidth="3"/><circle cx={x} cy={y} r="13" fill={i ? "#5c83c6" : "#cf6658"}/><text x={x+20} y={y+5}>{t}</text>{[0,1,2].map(j=><g key={j}><line x1={x+90} y1={y} x2="570" y2={y-45+j*45} stroke="#6c5738" strokeWidth="2"/><circle cx="570" cy={y-45+j*45} r="10" fill={["#7c9d55","#a46ab7","#d29b45"][j]}/></g>)}</g>)}<text x="610" y="155">6 outfits</text></svg><figcaption>Two shirt choices each lead to three trouser choices, so 2 × 3 = 6 outfits.</figcaption></figure>;
  if (type === "primary-paper-fold") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 270" role="img" aria-label="A square sheet folded in half and then unfolded, showing two layers"><rect x="50" y="35" width="190" height="190" fill="#fff8dc" stroke="#6b5534" strokeWidth="4"/><line x1="145" y1="35" x2="145" y2="225" stroke="#8f63a6" strokeWidth="4" strokeDasharray="10 8"/><path d="M210 85q-65-55-120 0" fill="none" stroke="#4d8e72" strokeWidth="5" markerEnd="url(#foldArrow)"/><defs><marker id="foldArrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0 0L9 3L0 6z" fill="#4d8e72"/></marker></defs><text x="145" y="252" textAnchor="middle">fold</text><path d="M320 130h65" stroke="#6b5534" strokeWidth="4" markerEnd="url(#foldArrow)"/><rect x="430" y="35" width="95" height="190" fill="#ead7f0" stroke="#6b5534" strokeWidth="4"/><rect x="525" y="35" width="95" height="190" fill="#f4e9f7" stroke="#6b5534" strokeWidth="4"/><text x="525" y="252" textAnchor="middle">2 layers</text></svg><figcaption>One fold in half places two layers of paper on top of each other.</figcaption></figure>;
  if (type === "intermediate-algebra-tiles") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 250" role="img" aria-label="Algebra tiles representing two x squared plus five x plus three"><rect x="40" y="35" width="150" height="150" fill="#9cc8bc" stroke="#315d54" strokeWidth="3"/><rect x="205" y="35" width="150" height="150" fill="#9cc8bc" stroke="#315d54" strokeWidth="3"/>{Array.from({length:5},(_,i)=><rect key={i} x={390+(i%3)*92} y={35+Math.floor(i/3)*68} width="78" height="52" fill="#e3b96f" stroke="#74501e" strokeWidth="3"/>)}{Array.from({length:3},(_,i)=><rect key={i} x={430+i*58} y="180" width="42" height="42" fill="#d9a6df" stroke="#693675" strokeWidth="3"/>)}<text x="115" y="120" textAnchor="middle">x²</text><text x="280" y="120" textAnchor="middle">x²</text><text x="360" y="235" textAnchor="middle">2x² + 5x + 3</text></svg><figcaption>Each tile keeps its identity: square terms, linear terms and constants combine only with matching kinds.</figcaption></figure>;
  if (type === "intermediate-compound-growth") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 300" role="img" aria-label="A curve showing compound growth rising faster than linear growth"><line x1="70" y1="250" x2="670" y2="250" stroke="#4d3a28" strokeWidth="3"/><line x1="70" y1="250" x2="70" y2="30" stroke="#4d3a28" strokeWidth="3"/><path d="M70 235C260 205 450 150 650 55" fill="none" stroke="#7b3f91" strokeWidth="6"/><path d="M70 235L650 105" fill="none" stroke="#5b9075" strokeWidth="4" strokeDasharray="10 8"/><text x="525" y="62">compound</text><text x="535" y="130">simple</text></svg><figcaption>Compound growth repeatedly acts on the new total, so its curve pulls away from simple growth.</figcaption></figure>;
  if (type === "intermediate-line-intersection") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 310" role="img" aria-label="Two straight-line graphs intersecting at the simultaneous solution"><line x1="60" y1="260" x2="670" y2="260" stroke="#4d3a28" strokeWidth="3"/><line x1="330" y1="290" x2="330" y2="25" stroke="#4d3a28" strokeWidth="3"/><line x1="90" y1="250" x2="625" y2="45" stroke="#4d8e72" strokeWidth="6"/><line x1="105" y1="45" x2="625" y2="245" stroke="#8a4ca0" strokeWidth="6"/><circle cx="365" cy="145" r="10" fill="#d6534d"/><line x1="365" y1="145" x2="365" y2="260" stroke="#d6534d" strokeDasharray="7 6"/><line x1="365" y1="145" x2="330" y2="145" stroke="#d6534d" strokeDasharray="7 6"/><text x="380" y="132">one point satisfies both equations</text></svg><figcaption>The intersection is the ordered pair that makes both equations true at once.</figcaption></figure>;
  if (type === "intermediate-expand-brackets-area") return <figure className="kq-lesson-figure"><svg viewBox="0 0 900 330" role="img" aria-label="A rectangle labelled x plus 3 by x plus 5, next to the same rectangle split into four smaller regions labelled x squared, 3x, 5x and 15"><rect x="40" y="60" width="300" height="220" fill="#ede3f5" stroke="#713b83" strokeWidth="3"/><text x="190" y="305" textAnchor="middle" fontWeight="700">x + 3</text><text x="18" y="170" textAnchor="middle" fontWeight="700" transform="rotate(-90 18 170)">x + 5</text><text x="190" y="175" textAnchor="middle" fontWeight="700" fontSize="20">(x + 3)(x + 5)</text><path d="M355 170h55m-14-14l14 14l-14-14m14 14l-14 14" fill="none" stroke="#4d3a28" strokeWidth="3"/><text x="382" y="140" textAnchor="middle" fontSize="13">splits into</text><rect x="430" y="60" width="280" height="140" fill="#ede3f5" stroke="#713b83" strokeWidth="3"/><rect x="710" y="60" width="160" height="140" fill="#fdeec4" stroke="#9b6820" strokeWidth="3"/><rect x="430" y="200" width="280" height="80" fill="#fdeec4" stroke="#9b6820" strokeWidth="3"/><rect x="710" y="200" width="160" height="80" fill="#f0d9d6" stroke="#a24c43" strokeWidth="3"/><text x="570" y="135" textAnchor="middle" fontWeight="700" fontSize="20">x²</text><text x="790" y="135" textAnchor="middle" fontWeight="700" fontSize="18">3x</text><text x="570" y="245" textAnchor="middle" fontWeight="700" fontSize="18">5x</text><text x="790" y="245" textAnchor="middle" fontWeight="700" fontSize="18">15</text><text x="570" y="300" textAnchor="middle" fontSize="14">x</text><text x="790" y="300" textAnchor="middle" fontSize="14">3</text><text x="402" y="100" textAnchor="middle" fontSize="14">x</text><text x="402" y="245" textAnchor="middle" fontSize="14">5</text></svg><figcaption>The rectangle (x + 3)(x + 5) splits into four smaller regions: x², 3x, 5x and 15. Adding the four regions gives x squared plus 8x plus 15.</figcaption></figure>;
  if (type === "intermediate-quadratic-roots") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 310" role="img" aria-label="An upward parabola crossing the x-axis at two roots"><line x1="55" y1="190" x2="670" y2="190" stroke="#4d3a28" strokeWidth="3"/><line x1="360" y1="285" x2="360" y2="20" stroke="#4d3a28" strokeWidth="3"/><path d="M110 35Q360 430 610 35" fill="none" stroke="#713b83" strokeWidth="7"/><circle cx="207" cy="190" r="9" fill="#d6534d"/><circle cx="513" cy="190" r="9" fill="#d6534d"/><text x="207" y="220" textAnchor="middle">root 1</text><text x="513" y="220" textAnchor="middle">root 2</text></svg><figcaption>The roots are the x-values where the quadratic graph crosses the x-axis.</figcaption></figure>;
  if (type === "intermediate-probability-tree") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 330" role="img" aria-label="A two-stage probability tree with branch probabilities"><text x="38" y="170">start</text>{[[210,85,"A","0.6"],[210,250,"not A","0.4"]].map(([x,y,t,p])=><g key={t}><line x1="80" y1="165" x2={x} y2={y} stroke="#54422e" strokeWidth="3"/><circle cx={x} cy={y} r="9" fill="#7d5793"/><text x="120" y={(165+y)/2-8}>{p}</text><text x={x+14} y={y+5}>{t}</text>{[[560,y-48,"B","0.3"],[560,y+48,"not B","0.7"]].map(([xx,yy,tt,pp])=><g key={tt}><line x1={x+70} y1={y} x2={xx} y2={yy} stroke="#54422e" strokeWidth="2"/><text x={x+175} y={(y+yy)/2-5}>{pp}</text><text x={xx+12} y={yy+5}>{tt}</text></g>)}</g>)}</svg><figcaption>Multiply along a route to find an intersection probability. Add different routes when either route can produce the event.</figcaption></figure>;
  if (type === "intermediate-circle-theorem") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 320" role="img" aria-label="A circle showing equal angles subtended by the same chord"><circle cx="360" cy="160" r="130" fill="#fffaf0" stroke="#5c405f" strokeWidth="5"/><line x1="245" y1="220" x2="475" y2="220" stroke="#b17b2e" strokeWidth="6"/><line x1="245" y1="220" x2="335" y2="42" stroke="#507c72" strokeWidth="4"/><line x1="475" y1="220" x2="335" y2="42" stroke="#507c72" strokeWidth="4"/><line x1="245" y1="220" x2="420" y2="55" stroke="#7a4c91" strokeWidth="4"/><line x1="475" y1="220" x2="420" y2="55" stroke="#7a4c91" strokeWidth="4"/><text x="335" y="80">θ</text><text x="420" y="92">θ</text></svg><figcaption>Angles standing on the same chord are equal when their vertices lie in the same segment.</figcaption></figure>;
  if (type === "intermediate-trig-triangle") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 320" role="img" aria-label="A right-angled triangle labelled opposite, adjacent and hypotenuse relative to theta"><polygon points="120,260 600,260 120,55" fill="#f3ead4" stroke="#4d3a28" strokeWidth="5"/><rect x="120" y="230" width="30" height="30" fill="none" stroke="#4d3a28" strokeWidth="3"/><path d="M535 260A65 65 0 0 0 548 225" fill="none" stroke="#8b4c96" strokeWidth="4"/><text x="535" y="240">θ</text><text x="360" y="292">adjacent</text><text x="72" y="165">opposite</text><text x="375" y="135" transform="rotate(-23 375 135)">hypotenuse</text></svg><figcaption>Name the sides relative to the chosen angle before selecting sine, cosine or tangent.</figcaption></figure>;
  if (type === "intermediate-histogram-area") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 320" role="img" aria-label="Histogram bars with unequal class widths showing that area represents frequency"><line x1="65" y1="270" x2="670" y2="270" stroke="#4d3a28" strokeWidth="3"/><line x1="65" y1="270" x2="65" y2="30" stroke="#4d3a28" strokeWidth="3"/><rect x="105" y="110" width="120" height="160" fill="#89b8ad" stroke="#3f6f65" strokeWidth="3"/><rect x="225" y="190" width="240" height="80" fill="#d8a6df" stroke="#754582" strokeWidth="3"/><rect x="465" y="70" width="80" height="200" fill="#e5b262" stroke="#805818" strokeWidth="3"/><text x="285" y="305">class width</text><text x="22" y="145" transform="rotate(-90 22 145)">frequency density</text></svg><figcaption>Histogram frequency is represented by bar area: class width × frequency density.</figcaption></figure>;
  if (type === "intermediate-surd-factorisation") return <figure className="kq-lesson-figure"><svg viewBox="0 0 720 250" role="img" aria-label="A factor diagram showing how the square factor thirty-six leaves the square root of seventy-two"><rect x="255" y="20" width="210" height="55" rx="12" fill="#f7eed8" stroke="#654b2d" strokeWidth="3"/><text x="360" y="57" textAnchor="middle">√72</text><line x1="330" y1="75" x2="230" y2="125" stroke="#765f3e" strokeWidth="3"/><line x1="390" y1="75" x2="490" y2="125" stroke="#765f3e" strokeWidth="3"/><rect x="140" y="125" width="180" height="55" rx="12" fill="#d9ead1" stroke="#527143" strokeWidth="3"/><rect x="400" y="125" width="180" height="55" rx="12" fill="#ead9ee" stroke="#70417b" strokeWidth="3"/><text x="230" y="161" textAnchor="middle">√36 = 6</text><text x="490" y="161" textAnchor="middle">√2 stays</text><text x="360" y="228" textAnchor="middle">√72 = 6√2</text></svg><figcaption>Split 72 into the square factor 36 and the remaining factor 2. The square root of 36 can leave the radical.</figcaption></figure>;
  return null;
}

function RichLesson({ data, color, onJumpToPrereq, sectionIndex = null }) {
  const [shown, setShown] = useState({});
  const toggle = (k) => setShown((s) => ({ ...s, [k]: !s[k] }));
  return (
    <div style={{ background: "#fff", borderRadius: 16, border: `2px solid ${color}44`, padding: "16px 18px", marginBottom: 14 }}>
      <div className="kq-display" style={{ fontWeight: 800, color: T.ink, fontSize: 20 }}>{data.title}</div>
      {data.prereq && data.prereq.length > 0 && (
        <div style={{ background: T.teal + "10", border: `2px solid ${T.teal}33`, borderRadius: 12, padding: "10px 14px", marginTop: 10 }}>
          <div style={{ fontWeight: 800, color: T.teal, fontSize: 12, marginBottom: 6 }}>📎 BEFORE THIS LESSON — worth a quick look first if any of these feel shaky:</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {data.prereq.map((p, i) => {
              const info = resolvePrereqInfo(p);
              return (
                <button key={i} onClick={() => onJumpToPrereq && onJumpToPrereq(p)} disabled={!onJumpToPrereq}
                  style={{ border: "none", background: "#fff", borderRadius: 999, padding: "6px 12px", fontWeight: 700, fontSize: 12.5, color: T.ink, cursor: onJumpToPrereq ? "pointer" : "default", boxShadow: "0 2px 0 rgba(42,26,94,.1)" }}>
                  {info.moduleLabel ? <span style={{ color: T.violet, fontWeight: 800 }}>{info.moduleLabel} · </span> : null}{info.title}
                </button>
              );
            })}
          </div>
        </div>
      )}
      {sectionIndex === null && data.intro && <p style={{ color: T.ink, fontWeight: 600, lineHeight: 1.65, marginTop: 12, whiteSpace: "pre-line" }}>{data.intro}</p>}
      {sectionIndex === null && data.learningPath && <div className="kq-lesson-learning-path" style={{ marginTop: 14, display: "grid", gap: 8 }}>
        {[["What you already know", data.learningPath.prior, "🌱"], ["The big idea", data.learningPath.idea, "💡"], ["How we will think", data.learningPath.method, "🧭"], ["How we will check", data.learningPath.check, "✓"], ["Tempting mistake", data.learningPath.watch, "⚠️"]].map(([label, text, icon]) => <div key={label} style={{ background: label === "Tempting mistake" ? T.coral + "10" : color + "0d", borderRadius: 11, padding: "9px 12px", color: T.ink, lineHeight: 1.55 }}><strong style={{ color: label === "Tempting mistake" ? T.coral : color }}>{icon} {label}: </strong><span style={{ fontWeight: 600 }}>{text}</span></div>)}
      </div>}
      {data.sections.map((s, i) => (sectionIndex === null || sectionIndex === i) && (
        <div key={i} style={{ marginTop: 18 }}>
          {s.image === "fractions-chocolate-five-eighths" && <figure className="kq-lesson-figure"><img src={FRACTIONS_CHOCOLATE_ART} alt="A chocolate bar divided into eight equal pieces, with five pieces highlighted" /><figcaption>Five of the eight equal pieces are highlighted, so the highlighted fraction is 5/8.</figcaption></figure>}
          {s.visual && <LessonVisual type={s.visual} />}
          <div className="kq-display" style={{ fontWeight: 800, color: color, fontSize: 16, marginBottom: 6 }}>{s.h}</div>
          {s.learningGoal && <div style={{ color, fontWeight: 800, fontSize: 13, margin: "0 0 9px" }}>🎯 {s.learningGoal}</div>}
          {s.body.map((p, j) => <p key={j} style={{ color: T.ink, fontWeight: 600, lineHeight: 1.65, margin: "0 0 9px", whiteSpace: "pre-line" }}>{p}</p>)}
          {s.note && <div style={{ background: T.yellow + "1e", border: `2px solid ${T.yellow}66`, borderRadius: 12, padding: "10px 13px", fontWeight: 700, color: T.ink, margin: "4px 0 10px", whiteSpace: "pre-line" }}>💡 {s.note}</div>}
          {(s.examples || (s.example ? [s.example] : [])).map((ex, exi, arr) => (
            <div key={exi} style={{ background: "#f7f4ff", borderRadius: 12, padding: "12px 14px", margin: "4px 0 10px" }}>
              <div className="kq-display" style={{ fontWeight: 700, color: T.violetDk, marginBottom: 4 }}>{arr.length > 1 ? `Example ${exi + 1}` : "Example"}</div>
              <div style={{ fontWeight: 700, color: T.ink, whiteSpace: "pre-line" }}>{ex.q}</div>
              {ex.solutionFormat === "clear" ? <>
                <div style={{ marginTop: 9, background: "#fff", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.teal }}>C · Comprehend (understand): </strong><span style={{ fontWeight: 600 }}>{ex.clear.comprehend}</span></div>
                <div style={{ marginTop: 7, background: "#fff", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.violetDk }}>L · Link the facts: </strong><span style={{ fontWeight: 600 }}>{ex.clear.link}</span></div>
                <div style={{ marginTop: 7, background: "#fff", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.violetDk }}>E · Explain the route: </strong><span style={{ fontWeight: 600 }}>{ex.clear.explain}</span></div>
                <div style={{ marginTop: 8, fontWeight: 800, color: T.ink }}>A · Apply it carefully:</div>
                <ol style={{ margin: "5px 0 0", paddingLeft: 20, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{ex.clear.apply.map((st, k) => <li key={k} style={{ whiteSpace: "pre-line", marginBottom: 4 }}>{st}</li>)}</ol>
                <div style={{ marginTop: 8, background: T.green + "10", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.green }}>R · Review and conclude: </strong><span style={{ fontWeight: 600 }}>{ex.clear.review}</span></div>
              </> : ex.solutionFormat === "state-work-conclude" ? <>
                <div style={{ marginTop: 9, background: "#fff", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.teal }}>STATE: </strong><span style={{ fontWeight: 600 }}>{ex.understand}</span></div>
                <div style={{ marginTop: 8, fontWeight: 800, color: T.ink }}>WORK:</div>
                <ol style={{ margin: "5px 0 0", paddingLeft: 20, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{ex.steps.map((st, k) => <li key={k} style={{ whiteSpace: "pre-line", marginBottom: 4 }}>{st}</li>)}</ol>
                <div style={{ marginTop: 8, background: T.green + "10", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.green }}>CONCLUDE: </strong><span style={{ fontWeight: 600 }}>{ex.conclusion} {ex.check}</span></div>
              </> : <>
                {ex.understand && <div style={{ marginTop: 9, background: "#fff", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.teal }}>Think: </strong><span style={{ fontWeight: 600 }}>{ex.understand}</span></div>}
                <div style={{ marginTop: 8, fontWeight: 800, color: T.ink }}>Work it through:</div>
                <ol style={{ margin: "5px 0 0", paddingLeft: 20, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{ex.steps.map((st, k) => <li key={k} style={{ whiteSpace: "pre-line", marginBottom: 4 }}>{st}</li>)}</ol>
                <div style={{ marginTop: 6, fontWeight: 800, color: T.green, whiteSpace: "pre-line" }}>Answer: {ex.answer}</div>
                {ex.check && <div style={{ marginTop: 8, background: T.green + "10", borderRadius: 9, padding: "8px 10px", color: T.ink, lineHeight: 1.6 }}><strong style={{ color: T.green }}>Check: </strong><span style={{ fontWeight: 600 }}>{ex.check}</span></div>}
              </>}
              {ex.watch && <div style={{ marginTop: 7, color: T.coral, fontWeight: 650, lineHeight: 1.5 }}>⚠️ Watch for this: {ex.watch}</div>}
            </div>
          ))}
          {s.misconception && <div style={{ background: T.coral + "0d", border: `1px solid ${T.coral}33`, borderRadius: 10, padding: "8px 11px", color: T.ink, fontWeight: 650, lineHeight: 1.55, margin: "3px 0 10px" }}><strong style={{ color: T.coral }}>Before moving on: </strong>{s.misconception}</div>}
          {s.tryit && <div style={{ background: T.teal + "12", border: `2px solid ${T.teal}44`, borderRadius: 12, padding: "12px 14px", margin: "4px 0 10px" }}>
            <div style={{ fontWeight: 800, color: T.teal, marginBottom: 4 }}>✏️ Your turn</div>
            <div style={{ fontWeight: 700, color: T.ink, whiteSpace: "pre-line" }}>{s.tryit.q}</div>
            {shown["t" + i] ? <div style={{ marginTop: 8, fontWeight: 700, color: T.ink, background: "#fff", borderRadius: 10, padding: "9px 12px", whiteSpace: "pre-line" }}>✅ {s.tryit.answer}</div>
              : <div style={{ marginTop: 8 }}><Btn small ghost color={T.teal} onClick={() => toggle("t" + i)}>Show answer</Btn></div>}
          </div>}
        </div>
      ))}
      {sectionIndex === null && data.recap && data.recap.length > 0 && <div style={{ marginTop: 18, background: color + "10", borderRadius: 12, padding: "12px 14px" }}>
        <div className="kq-display" style={{ fontWeight: 800, color: T.ink, marginBottom: 6 }}>🎯 Quick recap</div>
        <ul style={{ margin: 0, paddingLeft: 18, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{data.recap.map((r, i) => <li key={i}>{r}</li>)}</ul>
      </div>}
      {sectionIndex === null && data.mistakes && data.mistakes.length > 0 && <div style={{ marginTop: 12, background: T.coral + "12", border: `2px solid ${T.coral}44`, borderRadius: 12, padding: "12px 14px" }}>
        <div className="kq-display" style={{ fontWeight: 800, color: T.coral, marginBottom: 6 }}>⚠️ Common mistakes to dodge</div>
        <ul style={{ margin: 0, paddingLeft: 18, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{data.mistakes.map((m, i) => <li key={i}>{m}</li>)}</ul>
      </div>}
    </div>
  );
}


/* ---------------- Lessons library ----------------
   Every lesson in one browsable place, reachable at all times from the top bar so a
   player can learn any topic whenever they are stuck, not only inside "Learn" mode.
   Each topic expands to its lesson plus a fresh worked example (question + solution). */
function LessonLibrary({ setScreen, markLessonRead, jumpToPrereq, progress, activeModule }) {
  const [openKey, setOpenKey] = useState(null);
  const [sectionIndex, setSectionIndex] = useState(0);
  const readingPaneRef = useRef(null);
  const [query, setQuery] = useState("");
  const [examples, setExamples] = useState({});
  const readRef = useRef(new Set());
  useEffect(() => {
    if (openKey) readingPaneRef.current?.scrollTo({ top: 0, behavior: "auto" });
  }, [openKey, sectionIndex]);
  // Same recommended-order ranking used by the Practice topic picker, so a topic shows
  // the same "#N" in both places. Lessons carrying an explicit `order` (curriculum
  // sequence) sort by it; Array.sort is stable, so modules/topics with no `order` set
  // (Junior, Primary) just keep their existing hand-curated order, since order defaults
  // to the same Infinity for all of them.
  const order = topicOrderIndex();
  const byOrder = (a, b) => (order[a.key] ?? Infinity) - (order[b.key] ?? Infinity);
  const core = TOPICS.filter((t) => CONCEPTS[t.key] || LESSONS[t.key]).sort(byOrder);
  const deep = DEEP_TOPICS.filter((t) => CONCEPTS[t.key] || LESSONS[t.key]).sort(byOrder);
  const q = query.trim().toLowerCase();
  const match = (t) => !q || t.label.toLowerCase().includes(q);
  const visibleCore = core.filter(match);
  const visibleDeep = deep.filter(match);
  const visibleCount = visibleCore.length + visibleDeep.length;
  const openTopic = (t) => {
    const willOpen = openKey !== t.key;
    setOpenKey(willOpen ? t.key : null);
    if (willOpen) {
      const savedSection = progress.lessonHistory?.bookmarks?.[t.key];
      setSectionIndex(Number.isInteger(savedSection) ? savedSection : 0);
      if (!LESSONS[t.key] && !examples[t.key]) {
        try { const ex = makeLevelQuestion(t.deep ? 6 : 3, t.key, new Set()); setExamples((m) => ({ ...m, [t.key]: ex })); } catch (e) {}
      }
      if (!readRef.current.has(t.key)) { readRef.current.add(t.key); markLessonRead && markLessonRead(t.key, Number.isInteger(savedSection) ? savedSection : 0); }
    }
  };
  const row = (t) => {
    const isOpen = openKey === t.key; const ex = examples[t.key]; const rich = LESSONS[t.key];
    return (
      <div key={t.key} style={{ borderRadius: 20, border: `2px solid ${isOpen ? t.color + "88" : t.color + "32"}`, marginBottom: 12, overflow: "hidden", background: "#fffdf8", boxShadow: isOpen ? `0 12px 30px ${t.color}24` : "0 5px 0 rgba(42,26,94,.07)", transition: "border-color .2s, box-shadow .2s" }}>
        <div onClick={() => openTopic(t)} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 12, padding: "14px 16px", background: isOpen ? `linear-gradient(100deg, ${t.color}24, ${t.color}0d)` : `linear-gradient(100deg, ${t.color}12, transparent)` }}>
          <span style={{ width: 48, height: 48, flex: "0 0 48px", borderRadius: 15, display: "grid", placeItems: "center", fontSize: 25, background: `linear-gradient(145deg, #fff, ${t.color}20)`, border: `2px solid ${t.color}38`, boxShadow: `0 4px 0 ${t.color}24` }}>{t.emoji}</span>
          <span style={{ flex: 1, minWidth: 0 }}>
            <span className="kq-display" style={{ display: "block", fontWeight: 800, color: T.ink, fontSize: 17, lineHeight: 1.2 }}>{t.label}</span>
            <span style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 6, marginTop: 5 }}>
              {order[t.key] && <span style={{ color: t.color, fontWeight: 900, fontSize: 11, letterSpacing: ".04em" }}>LESSON {order[t.key]}</span>}
            </span>
          </span>
          <span style={{ width: 34, height: 34, flex: "0 0 34px", borderRadius: 12, display: "grid", placeItems: "center", background: isOpen ? t.color : t.color + "16", color: isOpen ? "#fff" : t.color, transition: "background .2s" }}><ChevronRight size={20} style={{ transform: isOpen ? "rotate(90deg)" : "none", transition: "transform .2s" }} /></span>
        </div>
        {isOpen && <div style={{ padding: "4px 14px 16px", borderTop: `1px solid ${t.color}20` }}>
          {rich ? <RichLesson data={rich} color={t.color} onJumpToPrereq={jumpToPrereq} /> : <>
            <Lesson topic={t.key} color={t.color} />
            {ex && <div style={{ background: "#f7f4ff", borderRadius: 14, padding: "12px 14px" }}>
              <div className="kq-display" style={{ fontWeight: 700, color: T.violetDk, marginBottom: 6 }}>Worked example</div>
              <div style={{ fontWeight: 700, color: T.ink }}>{ex.q}</div>
              <Diagram svg={ex.svg} />
              <ol style={{ margin: "8px 0 0", paddingLeft: 20, color: T.ink, fontWeight: 600, lineHeight: 1.7 }}>{(ex.solution || []).map((s, i) => <li key={i}>{s}</li>)}</ol>
              <div style={{ marginTop: 6, fontWeight: 800, color: T.green }}>Answer: {ex.options[ex.correctIndex]}</div>
            </div>}
          </>}
          <div style={{ marginTop: 10 }}><Btn small color={t.color} onClick={() => { setScreen("practice"); }}><Target size={15} /> Practise this in Quest</Btn></div>
        </div>}
      </div>
    );
  };
  if (["primary", "junior", "intermediate"].includes(activeModule)) {
    const theme = activeModule === "primary"
      ? { bookName: "Ninefold Orchard Study Book", quote: "Knowledge, like seeds, grows best with care.", mark: "❦", starter: "🍎" }
      : activeModule === "junior"
        ? { bookName: "Little Reckoning Lesson Ledger", quote: "Every mystery gets smaller when you write down what you know.", mark: "⚗", starter: "🧪" }
        : { bookName: "The Gifford Mathematical Compendium", quote: "A difficult problem is an invitation to look more carefully.", mark: "✦", starter: "📐" };
    const allTopics = [...core, ...deep];
    const history = progress.lessonHistory || { read: [], lastRead: null };
    const read = new Set(history.read || []);
    const lastTopic = allTopics.find((t) => t.key === history.lastRead);
    const selected = allTopics.find((t) => t.key === openKey);
    const selectedRich = selected && LESSONS[selected.key];
    const pct = allTopics.length ? Math.round(read.size / allTopics.length * 100) : 0;
    const indexRow = (t) => {
      const isSelected = openKey === t.key;
      const wasRead = read.has(t.key);
      const isLast = history.lastRead === t.key;
      return <button key={t.key} onClick={() => openTopic(t)} className={`kq-9fo-index-row${isSelected ? " selected" : ""}`} style={{ "--lesson-colour": t.color }}>
        {isLast && <span className="kq-9fo-bookmark">LAST READ</span>}
        <span className="kq-9fo-topic-icon">{t.emoji}</span>
        <span className="kq-9fo-topic-name">{t.label}</span>
        <span className="kq-9fo-page">p. {order[t.key] || "•"}</span>
        <span className={`kq-9fo-read-seal${wasRead ? " read" : ""}`}>{wasRead ? "✓" : ""}</span>
      </button>;
    };
    return <div className={`kq-9fo-lessons kq-lessons-${activeModule}`}>
      <button className="kq-9fo-home" onClick={() => setScreen("home")}><ArrowLeft size={18} /> Home</button>
      <main className={`kq-9fo-book${selected ? " lesson-open" : ""}`} aria-label={`${theme.bookName} lesson journal`}>
        <section className="kq-9fo-page-left">
          {selected && selectedRich ? <>
            <div className="kq-9fo-flourish">{theme.mark}</div>
            <h1>Contents</h1>
            {selectedRich.sections[0]?.image === "fractions-chocolate-five-eighths" && <img className="kq-lesson-opening-art" src={FRACTIONS_CHOCOLATE_ART} alt="A chocolate bar divided into eight equal pieces, with five highlighted" />}
            <p className="kq-lesson-opening-intro">{selectedRich.intro}</p>
            <div className="kq-9fo-index-scroll kq-lesson-section-list">
              {selectedRich.sections.map((section, i) => <button key={section.h} className={`kq-9fo-index-row${sectionIndex === i ? " selected" : ""}`} style={{ "--lesson-colour": selected.color }} onClick={() => { setSectionIndex(i); markLessonRead && markLessonRead(selected.key, i); }}>
                {history.bookmarks?.[selected.key] === i && <span className="kq-9fo-bookmark">LAST READ</span>}
                <span className="kq-9fo-topic-icon">{i + 1}</span>
                <span className="kq-9fo-topic-name">{section.h.replace(/^\d+\.\s*/, "")}</span>
                <ChevronRight size={18} />
              </button>)}
            </div>
          </> : <>
          <div className="kq-9fo-flourish">{theme.mark}</div>
          <h1>Index</h1>
          <div className="kq-9fo-search"><span>⌕</span><input aria-label="Find a lesson" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Find a lesson" /></div>
          <div className="kq-9fo-index-scroll">
            {visibleCore.length > 0 && <><h2>Core skills</h2>{visibleCore.map(indexRow)}</>}
            {visibleDeep.length > 0 && <><h2>Deep quests</h2>{visibleDeep.map(indexRow)}</>}
            {visibleCount === 0 && <div className="kq-9fo-empty">No lesson found. Try another word.</div>}
          </div>
          <div className="kq-9fo-vine">❧ · {theme.mark} · ❧</div>
          </>}
        </section>
        <section className="kq-9fo-page-right">
          {selected ? <>
            <button className="kq-9fo-close-lesson" onClick={() => setOpenKey(null)}>Back to lessons</button>
            <div className="kq-9fo-lesson-heading"><span>{selected.emoji}</span><div><div className="kq-9fo-kicker">LESSON {order[selected.key] || ""}</div><h1>{selected.label}</h1></div></div>
            <div ref={readingPaneRef} className="kq-9fo-reading-pane">
              {selectedRich ? <RichLesson data={selectedRich} color={selected.color} onJumpToPrereq={jumpToPrereq} sectionIndex={sectionIndex} /> : <Lesson topic={selected.key} color={selected.color} />}
            </div>
          </> : <>
            <div className="kq-9fo-title-mark">{theme.mark}</div>
            <h1 className="kq-9fo-title">Lessons</h1>
            <div className="kq-9fo-subtitle">{theme.bookName}</div>
            <div className="kq-9fo-rule">✦</div>
            <div className="kq-9fo-overview">
              <h2>Your learning trail</h2>
              <div className="kq-9fo-progress-copy"><strong>{read.size} of {allTopics.length}</strong> lessons read <span>{pct}%</span></div>
              <div className="kq-9fo-progress-track"><div style={{ width: `${pct}%` }} /></div>
              <div className="kq-9fo-apples" aria-hidden="true">{Array.from({ length: 10 }, (_, i) => <span key={i} className={i < Math.round(pct / 10) ? "done" : ""}>●</span>)}</div>
            </div>
            <div className="kq-9fo-continue">
              <div className="kq-9fo-continue-art">{lastTopic?.emoji || theme.starter}</div>
              <div><div className="kq-9fo-kicker">{lastTopic ? "CONTINUE READING" : "BEGIN YOUR JOURNEY"}</div><h2>{lastTopic?.label || allTopics[0]?.label}</h2><div>Page {order[lastTopic?.key || allTopics[0]?.key] || 1}</div></div>
              <button onClick={() => openTopic(lastTopic || allTopics[0])}><BookOpen size={17} /> Open lesson</button>
            </div>
            <blockquote>“{theme.quote}”</blockquote>
          </>}
        </section>
      </main>
    </div>;
  }
  return (<div className="kq-quest-board" style={{ maxWidth: 920 }}>
    <TopRow title="Lessons" onBack={() => setScreen("home")} light />
    <div style={{ position: "relative", overflow: "hidden", marginBottom: 16, padding: "24px 24px 20px", borderRadius: 28, color: "#fff", background: `linear-gradient(135deg, ${T.violetDk}, ${T.teal})`, border: `2px solid ${T.goldLight}88`, boxShadow: "0 12px 0 rgba(28,19,48,.18), 0 24px 45px rgba(28,19,48,.22)" }}>
      <div style={{ position: "absolute", width: 180, height: 180, borderRadius: "50%", right: -55, top: -80, background: "rgba(255,255,255,.09)" }} />
      <div style={{ position: "absolute", width: 90, height: 90, borderRadius: "50%", right: 90, bottom: -60, background: "rgba(255,255,255,.07)" }} />
      <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 16 }}>
        <div style={{ width: 68, height: 68, flex: "0 0 68px", borderRadius: 22, display: "grid", placeItems: "center", background: "rgba(255,255,255,.16)", border: "2px solid rgba(255,255,255,.28)", boxShadow: "inset 0 1px 0 rgba(255,255,255,.25)" }}><BookOpen size={34} /></div>
        <div>
          <div className="kq-display" style={{ fontSize: 25, fontWeight: 900, lineHeight: 1.1 }}>Your lesson journal</div>
          <div style={{ marginTop: 6, maxWidth: 600, fontWeight: 650, lineHeight: 1.45, opacity: .9 }}>Pick a topic, learn the key idea and try a worked example. Everything stays open, so you can explore in your own order.</div>
        </div>
      </div>
      <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 10, marginTop: 18, padding: "7px 8px 7px 15px", borderRadius: 18, background: "rgba(255,255,255,.96)", boxShadow: "0 6px 18px rgba(28,19,48,.18)" }}>
        <span aria-hidden="true" style={{ fontSize: 18 }}>🔎</span>
        <input aria-label="Search lessons" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search fractions, angles, averages…" style={{ minWidth: 0, flex: 1, padding: "8px 2px", border: "none", background: "transparent", fontFamily: "Nunito, sans-serif", fontSize: 16, fontWeight: 700, color: T.ink, outline: "none" }} />
        <span style={{ whiteSpace: "nowrap", padding: "7px 11px", borderRadius: 12, background: T.violet + "12", color: T.violetDk, fontSize: 12, fontWeight: 900 }}>{visibleCount} {visibleCount === 1 ? "topic" : "topics"}</span>
      </div>
    </div>
    {visibleCore.length > 0 && <section style={{ marginBottom: 20 }}><div style={{ display: "flex", alignItems: "center", gap: 10, margin: "4px 4px 11px" }}><span style={{ width: 36, height: 36, borderRadius: 12, display: "grid", placeItems: "center", background: "rgba(255,255,255,.16)", fontSize: 19 }}>📚</span><div><div className="kq-display" style={{ fontWeight: 900, fontSize: 19, color: "#fff" }}>Core topics</div><div style={{ color: "rgba(255,255,255,.72)", fontWeight: 700, fontSize: 12 }}>Build the skills every quest needs</div></div></div>{visibleCore.map(row)}</section>}
    {visibleDeep.length > 0 && <section><div style={{ display: "flex", alignItems: "center", gap: 10, margin: "4px 4px 11px" }}><span style={{ width: 36, height: 36, borderRadius: 12, display: "grid", placeItems: "center", background: "rgba(255,255,255,.16)", fontSize: 19 }}>🧭</span><div><div className="kq-display" style={{ fontWeight: 900, fontSize: 19, color: "#fff" }}>Deep quests</div><div style={{ color: "rgba(255,255,255,.72)", fontWeight: 700, fontSize: 12 }}>Join ideas together in multi-step problems</div></div></div>{visibleDeep.map(row)}</section>}
    {visibleCount === 0 && <Card style={{ textAlign: "center", padding: 30 }}><div style={{ fontSize: 34, marginBottom: 8 }}>🔭</div><div className="kq-display" style={{ fontWeight: 800, color: T.ink, fontSize: 18 }}>No lesson found</div><div style={{ marginTop: 4, fontWeight: 700, color: T.inkSoft }}>Try a different word from the topic name.</div></Card>}
  </div>);
}

/* ---------------- storage (profiles) ---------------- */
const P_KEY = "kq_profiles_v3", CUR_KEY = "kq_current_v3"; // v3: quest-era reset. Old v1 profiles are deliberately not migrated.
const profKey = (id) => "kq_prof3_" + id;
async function loadJSON(key) { try { if (!window.storage) return null; const r = await window.storage.get(key); return r ? JSON.parse(r.value) : null; } catch (e) { return null; } }
async function saveJSON(key, val) { try { if (!window.storage) return; await window.storage.set(key, JSON.stringify(val)); } catch (e) {} }
async function delKey(key) { try { if (!window.storage) return; await window.storage.delete(key); } catch (e) {} }
const NOTEPAD_PAGES = 5;
const freshNotepad = () => ({ page: 0, pages: Array.from({ length: NOTEPAD_PAGES }, () => ({ text: "", strokes: [] })) });
// tutorialSeen defaults to true so that merging this into an EXISTING saved profile (one
// from before the welcome tour existed) never retroactively pops the tour up for a returning
// player — only createProfile() explicitly flips it to false, for a genuinely brand-new profile.
//
// Phase 0 (see MODULE_EXPANSION_PLAN.md §2): progress now splits into fields shared across
// every module a profile plays (card ownership, currency, streaks — listed explicitly in
// SHARED_PROGRESS_KEYS) and fields describing progression through ONE module's own curriculum,
// which live under progress.modules[moduleKey]. Any field NOT listed in SHARED_PROGRESS_KEYS is
// treated as per-module by default (see unflattenProgress/migrateProgress below) — a deliberately
// conservative default, since a per-module field wrongly shared is far less likely than a truly
// shared field being missed off this list.
// stars/packs are deliberately NOT shared — each module earns and spends its own pack
// currency, so grinding Primary questions can't be cashed in on Junior's card pool.
const SHARED_PROGRESS_KEYS = ["xp", "badges", "streakDay", "lastDay", "sessionStreak", "lessonsRead", "cards", "cardItems", "notepad", "joeyDecks", "joeyActiveDeck"];

// tutorialSeen lives PER MODULE (not in SHARED_PROGRESS_KEYS) — a profile that's already
// toured Junior still gets the welcome tour the first time it tries Primary, since each
// module's tile layout is different enough to be worth walking through once.
const freshModuleProgress = () => ({ stars: 0, packs: 0, bestTest: 0, topicStats: {}, academy: {}, olympiad: {}, unlockedLevel: 1, bossesBeaten: 0, mocks: {}, chaptersRead: [], lessonHistory: { read: [], lastRead: null }, testHistory: [], adventures: {}, shinyBosses: [], shinyPasses: {}, packsSinceEpic: 0, packsSinceLegendary: 0, tutorialSeen: false,
  // Joey battle fields (§54 JOEY_SPEC.md)
  challengeTokens: 0, challengeUnlocked: {} });

const freshProgress = () => ({ xp: 0, badges: [], streakDay: 0, lastDay: null, sessionStreak: 0, lessonsRead: 0, cards: {}, cardItems: {}, notepad: freshNotepad(), modules: {},
  joeyDecks: [null, null, null, null, null], joeyActiveDeck: 0 });

// Migrates a pre-Phase-0 flat progress blob (every save that exists today — no `modules` key,
// every field at top level) into the split schema, nesting its per-module fields under
// modules.junior since every existing save IS Junior progress. Already-migrated progress
// (has a `modules` key) passes through untouched.
function migrateProgress(raw) {
  if (!raw) return freshProgress();
  if (raw.modules) return migrateJuniorCurriculumProgress(raw);
  const shared = {}, juniorFields = {};
  for (const k of Object.keys(raw)) (SHARED_PROGRESS_KEYS.includes(k) ? shared : juniorFields)[k] = raw[k];
  return migrateJuniorCurriculumProgress({ ...freshProgress(), ...shared, modules: { junior: { ...freshModuleProgress(), ...juniorFields } } });
}

const JUNIOR_TOPIC_MIGRATION = {
  multiExpr: "expressionsEquations", countIntegers: "placeValue", modular: "numberProperties",
  cryptarith: "placeValue", meanPuzzle: "statisticsMeasures", systemWord: "linearEquations",
  workBackwards: "linearEquations", multiRate: "percentProportion", inverseProp: "percentProportion",
  sportScore: "linearEquations", clockArith: "integerDecimalArithmetic", calendar: "sequences",
  angleParallel: "polygons", angleIso: "polygons", angleRhombus: "polygons",
  trianglesInRect: "perimeterArea", midpointSquare: "perimeterArea", partitionRect: "perimeterArea",
  compoundPerimeter: "perimeterArea", poolPath: "perimeterArea", cubeProps: "areaVolume",
  productOpt: "nonLinearRelations", tiling: "transformations", repeatOp: "sequences",
  customCount: "sequences", agePuzzle: "linearEquations", bouncing: "nonLinearRelations",
  shapeFold: "transformations", spatialTransform: "transformations", epicJourney: "percentProportion",
  moneyTrail: "percentProportion", digitDetective: "numberProperties", numberMachine: "expressionsFormulae",
  pythagQuest: "similarityPythagoras"
};

function migrateJuniorCurriculumProgress(stored) {
  const junior = stored.modules?.junior;
  if (!junior || junior.juniorCurriculumV2) return stored;
  const topicStats = { ...(junior.topicStats || {}) };
  for (const [oldKey, newKey] of Object.entries(JUNIOR_TOPIC_MIGRATION)) {
    const oldStat = topicStats[oldKey];
    if (!oldStat || oldKey === newKey) continue;
    const current = topicStats[newKey] || { correct: 0, total: 0, tier: 1, sinceUp: 0 };
    topicStats[newKey] = {
      correct: (current.correct || 0) + (oldStat.correct || 0),
      total: (current.total || 0) + (oldStat.total || 0),
      tier: Math.max(current.tier || 1, oldStat.tier || 1),
      sinceUp: Math.max(current.sinceUp || 0, oldStat.sinceUp || 0)
    };
    delete topicStats[oldKey];
  }
  return { ...stored, modules: { ...stored.modules, junior: { ...junior, topicStats, juniorCurriculumV2: true } } };
}

// One-time fixup for the bossCardId collision: it used to be module-agnostic ("boss"+n),
// so every module's Nth boss shared one key in the shared `cards` object — beating boss 3
// in Junior made Primary's (and Intermediate's) boss-3 trophy show as already owned too,
// with no fighting or strength required there. Every surviving old-style "bossN" key
// belongs to Junior (no other module could have granted one before this fix existed), so
// this renames them to the new "boss_junior_N" scheme. Idempotent — a no-op once run.
function migrateBossCardIds(progress) {
  const OLD_KEY_RE = /^boss(\d+)$/;
  const cards = progress.cards || {};
  const oldKeys = Object.keys(cards).filter((k) => OLD_KEY_RE.test(k));
  if (!oldKeys.length) return progress;
  const newCards = { ...cards };
  for (const k of oldKeys) { const n = k.match(OLD_KEY_RE)[1]; newCards[`boss_junior_${n}`] = cards[k]; delete newCards[k]; }
  return { ...progress, cards: newCards };
}

// One-time fixup for boss defeats that predate the Joey reveal-token wiring (beatBoss only
// grants a token the moment a boss is FIRST defeated — see beatBoss's `if (bossesBeaten >= n)
// return p` guard, which never re-fires for a boss already beaten). Any save whose bosses were
// beaten before that wiring existed is stuck at 0 tokens for those defeats forever. Recomputes
// the correct balance from first principles — one token per boss beaten (capped at 10) minus
// one per card already revealed — and tops up only if the stored balance is short, so a
// player's current balance (topped up before, or spent down since) is never reduced.
// Idempotent — a no-op once a module's balance already matches.
function migrateChallengeTokens(stored) {
  if (!stored.modules) return stored;
  const modules = { ...stored.modules };
  for (const key of Object.keys(modules)) {
    const mp = modules[key];
    const earned = Math.min(mp.bossesBeaten || 0, 10);
    const spent = Object.values(mp.challengeUnlocked || {}).filter(Boolean).length;
    const correctBalance = Math.max(0, earned - spent);
    if ((mp.challengeTokens || 0) < correctBalance) modules[key] = { ...mp, challengeTokens: correctBalance };
  }
  return { ...stored, modules };
}

// The object every screen component actually reads/writes as `progress` — the active module's
// bucket merged flat onto the shared fields, so none of the app's existing `progress.xxx`
// call sites (100+ of them) need to know the split schema exists.
function flattenProgress(stored, moduleKey) {
  const bucket = (stored.modules && stored.modules[moduleKey]) || freshModuleProgress();
  return { ...stored, ...bucket };
}

// Un-flattens an update produced against the flattened view back into the split shape: shared
// keys go back to the top level, everything else lands in modules[moduleKey].
function unflattenProgress(flat, moduleKey) {
  const shared = {}, moduleFields = {};
  for (const k of Object.keys(flat)) { if (k === "modules") continue; (SHARED_PROGRESS_KEYS.includes(k) ? shared : moduleFields)[k] = flat[k]; }
  return { shared, moduleFields };
}
// Dev shortcut: builds a fully-unlocked progress object for the "test" profile —
// every card and boss trophy owned, every adventure completed and upgraded,
// every academy module and chapter done, every boss beaten, every mock cleared
// with a shiny claim banked and spent — so every screen and gate is exercisable
// immediately without having to play the whole game through first.
function maxedTestProgress(base) {
  const cards = {};
  for (const mk of ["primary", "junior", "intermediate"]) {
    const m = MODULES[mk];
    for (const c of m.CARDS) cards[c.id] = 1;
    for (const b of m.BOSSES) cards[bossCardId(b.n, mk)] = 1;
  }
  const cardItems = {}, adventures = {};
  for (const heroId of ADVENTURE_HEROES) {
    cardItems[heroId] = ADVENTURES[heroId].items.map((it) => it.id);
    adventures[heroId] = { done: true };
  }
  const academy = {};
  for (const m of ACADEMY) academy[m.id] = { step: 0, done: true };
  const olympiad = {};
  for (const p of OLYMPIAD) olympiad[p.id] = { attempted: true, bestMarks: olympiadMarksTotal(p), marksTotal: olympiadMarksTotal(p) };
  const testHistory = [
    { date: Date.now(), kind: "level-4",  score: 25, correct: 25, towerLevel: 4 },
    { date: Date.now(), kind: "level-8",  score: 25, correct: 25, towerLevel: 8 },
    { date: Date.now(), kind: "level-10", score: 25, correct: 25, towerLevel: 10 },
  ];
  // Phase 0: this shortcut only maxes out Junior (the only module with real content yet) —
  // shared fields go to the top level, curriculum-progression fields into modules.junior.
  return {
    ...base,
    xp: 9999, badges: Object.keys(BADGES), streakDay: 30, lessonsRead: 999,
    cards, cardItems,
    modules: {
      ...base.modules,
      junior: {
        ...freshModuleProgress(), ...(base.modules && base.modules.junior),
        tutorialSeen: true, stars: 999, packs: 99,
        academy, olympiad, unlockedLevel: MAX_LEVEL, bossesBeaten: MAX_LEVEL,
        mocks: Object.fromEntries(BOSSES.map((b) => [b.n, true])),
        chaptersRead: STORY.map((c) => c.n),
        testHistory, bestTest: 135, adventures,
        shinyBosses: BOSSES.map((b) => b.n),
        shinyPasses: { "level-4": 1, "level-8": 1, "level-10": 1 },
      },
    },
  };
}
const todayStr = () => new Date().toISOString().slice(0, 10);
function applyDailyStreak(p) {
  const today = todayStr();
  if (p.lastDay === today) return p;
  const y = new Date(); y.setDate(y.getDate() - 1); const yest = y.toISOString().slice(0, 10);
  const streakDay = p.lastDay === yest ? (p.streakDay || 0) + 1 : 1;
  const badges = [...(p.badges || [])];
  if (streakDay >= 3 && !badges.includes("weekStreak")) badges.push("weekStreak");
  return { ...p, streakDay, lastDay: today, badges };
}

/* ---------------- TITLE SCREEN ---------------- */
// Phases: idle (click to begin) -> holding (dims, title theme starts, brief hold) ->
// modal (account-choice modal fades in over the still-dimmed, still-playing title art).
// The title art and its music never actually go away until a profile is chosen.
function TitleScreen({ profiles, onChoose, onCreate, onDelete, onChangeAvatar, onExport, onValidateImport, onApplyImport, onSyncLogin, onStartGoogleSignIn, onFinishGoogleSignIn }) {
  const [phase, setPhase] = useState("idle");
  const startedRef = useRef(false);
  const handleClick = () => {
    if (startedRef.current) return; // this click is a genuine gesture, so audio can actually start here
    startedRef.current = true;
    musicEngine.playLoop("title").catch(() => {});
    setPhase("holding");
    setTimeout(() => setPhase("modal"), 5000);
  };
  return (
    <div className={"kq-title-screen" + (phase !== "idle" ? " kq-title-holding" : "")} onClick={phase === "idle" ? handleClick : undefined} role="button" aria-label="Click to begin">
      <img className="kq-title-layer kq-title-bg" src={TITLE_ART.background} alt="" />
      <img className="kq-title-layer kq-title-front" src={TITLE_ART.front} alt="" />
      <img className="kq-title-layer kq-title-logo" src={TITLE_ART.title} alt="Kangaroo Maths Quest" />
      <img className="kq-title-layer kq-title-mascot" src={TITLE_ART.mascot} alt="" />
      {phase !== "modal" && <div className="kq-title-prompt">{phase === "holding" ? "Loading your quest…" : "CLICK TO BEGIN"}</div>}
      {phase === "modal" && (
        <div className="kq-title-modal-backdrop" style={{ backgroundImage: `url(${PLAYER_SELECTOR_ART})` }}>
          <div className="kq-title-modal-card">
            <Profiles cinematic profiles={profiles} onChoose={onChoose} onCreate={onCreate} onDelete={onDelete} onChangeAvatar={onChangeAvatar} canCancel={false} onExport={onExport} onValidateImport={onValidateImport} onApplyImport={onApplyImport} onSyncLogin={onSyncLogin} onStartGoogleSignIn={onStartGoogleSignIn} onFinishGoogleSignIn={onFinishGoogleSignIn} />
          </div>
        </div>
      )}
    </div>
  );
}

