// Swaps in the active module's own world/story text for the handful of steps above
// that reference lore by name, leaving the purely-UI steps untouched.
function tourStepsForModule(module) {
  const lore = MODULE_LORE[module] || MODULE_LORE.junior;
  return TOUR_STEPS.map((s) => {
    if (s.target === null && s.title.startsWith("Welcome")) return { ...s, title: lore.welcomeTitle, body: lore.welcomeBody };
    if (s.target === "boss-card") return { ...s, body: lore.bossLine };
    if (s.target === "tile-storybook") return { ...s, body: lore.storybookLine };
    if (s.target === "tile-test") return { ...s, body: lore.examLine };
    if (s.target === null && s.title.startsWith("You're ready")) return { ...s, body: lore.readyLine };
    return s;
  });
}

// Polls the target element's on-screen position every animation frame while the tour is
// active. A rAF loop (rather than separate scroll/resize listeners) is the simplest way to
// stay correct through smooth-scrolling, window resizes and orientation changes alike —
// the same handful of tiles just live at different coordinates on a laptop vs a phone.
function useTourRect(targetKey) {
  const [rect, setRect] = useState(undefined);
  const scrolledRef = useRef(null);
  // Every real target (browser or Capacitor WebView) has requestAnimationFrame; this fallback
  // just means the polling loop degrades to a plain timer instead of throwing in an
  // environment that somehow lacks it.
  const raf1 = typeof requestAnimationFrame === "function" ? requestAnimationFrame : (cb) => setTimeout(cb, 16);
  const caf1 = typeof cancelAnimationFrame === "function" ? cancelAnimationFrame : clearTimeout;
  useEffect(() => {
    scrolledRef.current = null;
    if (!targetKey) { setRect(null); return; }
    let raf = 0, alive = true;
    const loop = () => {
      if (!alive) return;
      const el = document.querySelector(`[data-tour="${targetKey}"]`);
      if (el) {
        if (scrolledRef.current !== targetKey) { scrolledRef.current = targetKey; if (el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "center" }); }
        const r = el.getBoundingClientRect();
        setRect((prev) => (prev && prev.top === r.top && prev.left === r.left && prev.width === r.width && prev.height === r.height) ? prev : { top: r.top, left: r.left, width: r.width, height: r.height });
      } else {
        setRect((prev) => (prev === undefined ? prev : undefined));
      }
      raf = raf1(loop);
    };
    raf = raf1(loop);
    return () => { alive = false; caf1(raf); };
  }, [targetKey]);
  return rect;
}

function TourOverlay({ step, stepIndex, totalSteps, onNext, onExit }) {
  const rect = useTourRect(step.target);
  // Target not found (element unmounted, e.g. a step whose element briefly isn't rendered) —
  // skip it automatically rather than getting stuck on a highlight that never appears.
  useEffect(() => { if (step.target && rect === undefined) { const t = setTimeout(() => onNext(), 900); return () => clearTimeout(t); } }, [step.target, rect, onNext]);
  if (step.target && rect === undefined) return null;
  const vw = window.innerWidth, vh = window.innerHeight;
  const pad = 8;
  // width/height are clamped to the viewport — some tour targets (the new full-height
  // pack/boss meter bars) are taller than the screen itself, and an unclamped box here
  // pushed both the highlight ring and the card's computed position off-screen entirely.
  const box = rect ? { top: Math.max(4, rect.top - pad), left: Math.max(4, rect.left - pad), width: Math.min(rect.width + pad * 2, vw - 8), height: Math.min(rect.height + pad * 2, vh - 8) } : null;
  const cardW = Math.min(340, vw - 32);
  let cardStyle;
  if (box) {
    const spaceBelow = vh - (box.top + box.height), spaceAbove = box.top;
    const placeBelow = spaceBelow > 160 || spaceBelow >= spaceAbove;
    let left = box.left + box.width / 2 - cardW / 2;
    left = Math.max(16, Math.min(left, vw - cardW - 16));
    cardStyle = placeBelow
      ? { position: "fixed", left, width: cardW, top: Math.max(40, Math.min(box.top + box.height + 14, vh - 40)) }
      : { position: "fixed", left, width: cardW, bottom: Math.max(40, Math.min(vh - box.top + 14, vh - 40)) };
  } else {
    cardStyle = { position: "fixed", left: "50%", top: "50%", transform: "translate(-50%,-50%)", width: cardW };
  }
  return (<>
    <div style={{ position: "fixed", inset: 0, zIndex: 300, background: box ? "transparent" : "rgba(20,10,45,.74)" }} />
    {box && <div style={{ position: "fixed", top: box.top, left: box.left, width: box.width, height: box.height, borderRadius: 16, boxShadow: "0 0 0 9999px rgba(20,10,45,.74)", border: `3px solid ${T.yellow}`, zIndex: 300, pointerEvents: "none" }} />}
    <div style={{ ...cardStyle, zIndex: 301, background: T.white, borderRadius: 18, padding: "18px 20px", boxShadow: "0 20px 50px rgba(0,0,0,.35)", maxHeight: "70vh", overflowY: "auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
        <span style={{ fontSize: 11, fontWeight: 800, color: T.inkSoft, letterSpacing: 1 }}>STEP {stepIndex + 1} OF {totalSteps}</span>
        <button onClick={onExit} title="Close" style={{ border: "none", background: "transparent", color: T.inkSoft, fontSize: 20, cursor: "pointer", lineHeight: 1, padding: 2 }}>×</button>
      </div>
      <div className="kq-display" style={{ fontSize: 19, fontWeight: 700, color: T.ink }}>{step.title}</div>
      <div style={{ color: T.inkSoft, fontWeight: 600, fontSize: 14, marginTop: 8, lineHeight: 1.5 }}>{step.body}</div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 16, gap: 10 }}>
        <button onClick={onExit} style={{ border: "none", background: "transparent", color: T.inkSoft, fontWeight: 700, fontSize: 13, cursor: "pointer", padding: "8px 4px" }}>Skip tour</button>
        <Btn color={T.violet} onClick={onNext}>{stepIndex + 1 === totalSteps ? "Finish" : "Next →"}</Btn>
      </div>
    </div>
  </>);
}

// A profile syncs via exactly one method — the app never requests a Google token for a
// username+PIN profile or vice versa — so these two helpers are the single place that decides
// which transport a given profile uses. Both mirror sync.js's contract: every failure mode
// (no sync method, auth failure, network failure) resolves to {ok:false, error}, never throws.
async function pushForProfile(prof, progress) {
  const payload = { profile: { name: prof.name, avatar: prof.avatar, activeModule: prof.activeModule }, progress };
  if (prof.syncCode) return pushProgress(prof.syncCode.username, prof.syncCode.pin, payload);
  if (prof.driveSync) {
    const tok = await requestGoogleToken({ interactive: false });
    if (!tok.ok) return tok;
    return pushToDrive(tok.accessToken, payload);
  }
  return { ok: false, error: "no_sync_method" };
}
async function pullForProfile(prof) {
  if (prof.syncCode) return pullProgress(prof.syncCode.username, prof.syncCode.pin);
  if (prof.driveSync) {
    const tok = await requestGoogleToken({ interactive: false });
    if (!tok.ok) return tok;
    return pullFromDrive(tok.accessToken);
  }
  return { ok: false, error: "no_sync_method" };
}

