  const [loaded, setLoaded] = useState(false);
  const [celebrate, setCelebrate] = useState(false);
  const [sound, setSound] = useState(true);
  const [newBadge, setNewBadge] = useState(null);
  const [packReady, setPackReady] = useState(false);
  const [storyChapter, setStoryChapter] = useState(null); // chapter object shown in the post-boss popup
  const [globalReader, setGlobalReader] = useState(null); // chapter opened by clicking a boss portrait
  const [lessonTopic, setLessonTopic] = useState(null); // topic key opened via a question's "Full lesson" button
  const [prereqReturnModule, setPrereqReturnModule] = useState(null); // module to switch back to once a cross-module prereq lesson is closed
  const [notepadOpen, setNotepadOpen] = useState(false);
  const [musicContext, setMusicContext] = useState("ambient"); // "ambient" | "boss" | "adventure"
